<?php
namespace App\Filament\Pages;
use App\Models\CitySeoPage;use App\Models\Setting;use App\Services\{AdminAudit,CitySeoService,ContentSanitizer};use Filament\Forms\Components\{RichEditor,Select,TextInput,Textarea};use Filament\Notifications\Notification;use Filament\Pages\Page;use Filament\Schemas\Schema;
class CitySeoPages extends Page {protected static ?string $slug='pages-villes-seo';protected static ?string $title='Pages villes SEO';protected static ?string $navigationLabel='Pages villes SEO';protected static string|\BackedEnum|null $navigationIcon='heroicon-o-map';protected static string|\UnitEnum|null $navigationGroup='Contenu';protected static ?int $navigationSort=2;protected string $view='filament.pages.city-seo-pages';public ?array $data=[];public string $cityName='';public function mount():void{$this->data=['threshold'=>app(CitySeoService::class)->threshold(),'state'=>'auto'];}public function form(Schema $schema):Schema{return $schema->components([TextInput::make('threshold')->label('Nombre minimum de restaurants pour ouvrir automatiquement une page ville')->integer()->minValue(1)->required(),Select::make('state')->label('État')->options(['auto'=>'Automatique','forced_open'=>'Forcée ouverte','forced_closed'=>'Forcée fermée'])->required(),TextInput::make('h1')->label('H1 personnalisé')->maxLength(255),TextInput::make('seo_title')->label('Title personnalisé')->maxLength(255),Textarea::make('seo_description')->label('Meta description personnalisée')->rows(3)->maxLength(500),RichEditor::make('content_top')->label('Contenu haut'),RichEditor::make('content_bottom')->label('Contenu bas')])->statePath('data');}public function selectCity(string $city):void{$this->cityName=$city;$config=CitySeoPage::firstWhere('city_name',$city);$this->form->fill(['threshold'=>app(CitySeoService::class)->threshold(),'state'=>$config?->state??'auto','h1'=>$config?->h1,'seo_title'=>$config?->seo_title,'seo_description'=>$config?->seo_description,'content_top'=>$config?->content_top,'content_bottom'=>$config?->content_bottom]);}public function save():void{$data=$this->form->getState();Setting::updateOrCreate(['key'=>'city_seo_minimum_restaurants'],['value'=>['value'=>(int)$data['threshold']],'group'=>'seo']);if($this->cityName!==''){foreach(['content_top','content_bottom'] as $key)$data[$key]=app(ContentSanitizer::class)->sanitize($data[$key]??'')['html'];unset($data['threshold']);CitySeoPage::updateOrCreate(['city_name'=>$this->cityName],$data);}app(CitySeoService::class)->forget();app(AdminAudit::class)->record('city_seo.updated','city_seo',$this->cityName?:['threshold']);Notification::make()->title('Réglages enregistrés')->success()->send();}public function getCitiesProperty(){return app(CitySeoService::class)->cities();}}
